const sources = [
  { id: 'hn', name: 'Hacker News (Front Page)', url: 'https://hnrss.org/frontpage' },
  { id: 'techcrunch', name: 'TechCrunch', url: 'https://techcrunch.com/feed/' },
  { id: 'bbc-tech', name: 'BBC Technology', url: 'https://feeds.bbci.co.uk/news/technology/rss.xml' },
];
return sources.map((s) => ({ json: s }));

function decodeXml(s) {
  return String(s || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#8217;/g, "'")
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const sourceItems = $('List Sources').all();
const fetchItems = $input.all();
const results = [];

for (let i = 0; i < fetchItems.length; i++) {
  const source = sourceItems[i] ? sourceItems[i].json : { id: 'unknown', name: 'Unknown', url: '' };
  let xml = fetchItems[i].json;
  if (typeof xml !== 'string') {
    if (xml && typeof xml.data === 'string') xml = xml.data;
    else if (xml && typeof xml.body === 'string') xml = xml.body;
    else xml = JSON.stringify(xml);
  }
  if (!xml || (!xml.includes('<item') && !xml.includes('<entry'))) continue;

  let match;
  const itemRe = /<item[\s\S]*?<\/item>/gi;
  let count = 0;
  while ((match = itemRe.exec(xml)) !== null && count < 8) {
    const block = match[0];
    const title = decodeXml((block.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '');
    const link = decodeXml((block.match(/<link[^>]*>([\s\S]*?)<\/link>/i) || [])[1] || '');
    const description = decodeXml((block.match(/<description[^>]*>([\s\S]*?)<\/description>/i) || [])[1] || '');
    const pubDate = decodeXml((block.match(/<pubDate[^>]*>([\s\S]*?)<\/pubDate>/i) || [])[1] || '');
    if (!title || !link) continue;
    results.push({ json: { source_id: source.id, source_name: source.name, title, url: link, snippet: description.slice(0, 500), published_at: pubDate || null } });
    count += 1;
  }

  if (count === 0) {
    const entryRe = /<entry[\s\S]*?<\/entry>/gi;
    while ((match = entryRe.exec(xml)) !== null && count < 8) {
      const block = match[0];
      const title = decodeXml((block.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '');
      let link = '';
      const linkHref = block.match(/<link[^>]*href=["']([^"']+)["'][^>]*>/i);
      if (linkHref) link = linkHref[1];
      else link = decodeXml((block.match(/<link[^>]*>([\s\S]*?)<\/link>/i) || [])[1] || '');
      const description = decodeXml((block.match(/<summary[^>]*>([\s\S]*?)<\/summary>/i) || [])[1] || (block.match(/<content[^>]*>([\s\S]*?)<\/content>/i) || [])[1] || '');
      const pubDate = decodeXml((block.match(/<updated[^>]*>([\s\S]*?)<\/updated>/i) || [])[1] || (block.match(/<published[^>]*>([\s\S]*?)<\/published>/i) || [])[1] || '');
      if (!title || !link) continue;
      results.push({ json: { source_id: source.id, source_name: source.name, title, url: link, snippet: description.slice(0, 500), published_at: pubDate || null } });
      count += 1;
    }
  }
}

const seen = new Set();
const unique = [];
for (const row of results) {
  let key;
  try {
    const u = new URL(row.json.url);
    key = (u.hostname + u.pathname).toLowerCase().replace(/\/$/, '');
  } catch {
    key = row.json.title.toLowerCase();
  }
  if (seen.has(key)) continue;
  seen.add(key);
  unique.push(row);
}

const bySource = {};
for (const row of unique) {
  const id = row.json.source_id;
  bySource[id] = bySource[id] || [];
  bySource[id].push(row);
}
const selected = [];
const ids = Object.keys(bySource);
let i = 0;
while (selected.length < 6 && ids.some((id) => bySource[id].length)) {
  const id = ids[i % ids.length];
  if (bySource[id].length) selected.push(bySource[id].shift());
  i += 1;
}
return selected;

const items = $input.all();
const apiKey = $env.GEMINI_API_KEY;
if (!apiKey) {
  throw new Error('GEMINI_API_KEY is not available in the n8n environment');
}

const model = 'gemini-3.5-flash';
const out = [];
let lastError = null;

for (let idx = 0; idx < items.length; idx++) {
  const entry = items[idx];
  if (idx > 0) {
    await new Promise((r) => setTimeout(r, 3000));
  }
  const item = entry.json;
  const prompt = `You are a research analyst for a content workflow.
Analyze the article below and return ONLY valid JSON (no markdown fences) with this exact shape:
{
  "summary": "2-3 sentence summary",
  "category": "one of: AI, Startups, Security, Developer Tools, Business, Science, Other",
  "key_points": ["point1", "point2", "point3"],
  "relevance_score": 1-10 integer (10 = highly relevant to AI/automation/product builders)
}

Title: ${item.title}
Source: ${item.source_name}
URL: ${item.url}
Snippet: ${item.snippet}`;

  const body = {
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    generationConfig: { temperature: 0.2, responseMimeType: 'application/json' },
  };

  let analysis = null;
  for (let attempt = 0; attempt < 4; attempt++) {
    try {
      const response = await this.helpers.httpRequest({
        method: 'POST',
        url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
        headers: { 'Content-Type': 'application/json' },
        body,
        json: true,
        timeout: 90000,
      });
      const text = (response.candidates && response.candidates[0] && response.candidates[0].content && response.candidates[0].content.parts)
        ? response.candidates[0].content.parts.map((p) => p.text || '').join('')
        : '';
      try {
        analysis = JSON.parse(text);
      } catch (e) {
        const m = String(text).match(/\{[\s\S]*\}/);
        if (!m) throw new Error('Gemini returned non-JSON');
        analysis = JSON.parse(m[0]);
      }
      break;
    } catch (err) {
      lastError = err;
      const msg = String(err.message || err);
      if (!/timeout|503|UNAVAILABLE|429|ECONNRESET|socket/i.test(msg) || attempt === 3) break;
      await new Promise((r) => setTimeout(r, 2000 * (attempt + 1)));
    }
  }

  if (!analysis) {
    // Skip failed items but keep going
    continue;
  }

  const score = Math.max(1, Math.min(10, Number(analysis.relevance_score) || 5));
  out.push({
    json: {
      title: item.title,
      url: item.url,
      source_id: item.source_id,
      source_name: item.source_name,
      snippet: item.snippet,
      published_at: item.published_at,
      summary: String(analysis.summary || '').trim(),
      category: String(analysis.category || 'Other').trim(),
      key_points: Array.isArray(analysis.key_points) ? analysis.key_points.map(String).slice(0, 5) : [],
      relevance_score: score,
      processed_at: new Date().toISOString(),
      model,
    },
  });
}

if (!out.length) {
  throw new Error(`Gemini analyze produced 0 rows. Last error: ${lastError && lastError.message ? lastError.message : lastError}`);
}
return out;

const rows = $input.all().map((i) => i.json);
rows.sort((a, b) => b.relevance_score - a.relevance_score || String(a.title).localeCompare(String(b.title)));
const payload = {
  generated_at: new Date().toISOString(),
  workflow: 'research-content-workflow-demo',
  executed_in: 'n8n',
  model: rows[0] && rows[0].model ? rows[0].model : 'gemini-3.5-flash',
  item_count: rows.length,
  items: rows,
};
const jsonText = JSON.stringify(payload, null, 2);

function toCsv(rows) {
  const headers = ['title','url','source_name','category','relevance_score','summary','key_points','published_at','processed_at'];
  const esc = (v) => {
    const s = String(v ?? '');
    if (/[",\n]/.test(s)) return '"' + s.replace(/"/g, '""') + '"';
    return s;
  };
  const lines = [headers.join(',')];
  for (const r of rows) {
    lines.push([
      r.title, r.url, r.source_name, r.category, r.relevance_score, r.summary,
      (r.key_points || []).join(' | '), r.published_at, r.processed_at
    ].map(esc).join(','));
  }
  return lines.join('\n') + '\n';
}

const csvText = toCsv(rows);
const fs = require('fs');
const outDir = '/workspace/n8n-research-demo/output';
const sampleDir = '/workspace/n8n-research-demo/sample-output';
const dashDir = '/workspace/n8n-research-demo/dashboard';
fs.mkdirSync(outDir, { recursive: true });
fs.mkdirSync(sampleDir, { recursive: true });
fs.mkdirSync(dashDir, { recursive: true });
fs.writeFileSync(`${outDir}/research-results.json`, jsonText);
fs.writeFileSync(`${outDir}/research-results.csv`, csvText);
fs.writeFileSync(`${sampleDir}/research-results.json`, jsonText);
fs.writeFileSync(`${sampleDir}/research-results.csv`, csvText);
fs.writeFileSync(`${dashDir}/data.json`, jsonText);
fs.writeFileSync('/tmp/n8n-research-output.json', jsonText);

return [{ json: { ...payload, files_written: [
  `${outDir}/research-results.json`,
  `${outDir}/research-results.csv`,
  `${sampleDir}/research-results.json`,
  `${dashDir}/data.json`,
] } }];
